// components/ButtonLink.js
import Link from 'next/link';

const ButtonLink = React.forwardRef(({ onClick, href }, ref) => {
  return (
    <a href={href} onClick={onClick} ref={ref} className="btn">
      Click me
    </a>
  );
});

// Usage
<Link href="/about" passHref>
  <ButtonLink />
</Link>
